import{_ as t,o,c as s,a5 as r}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"开始","description":"每一个 Vuex 应用的核心就是 store（仓库）。“store”基本上就是一个容器，它包含着你的应用中大部分的状态 (state)。Vuex 和单纯的全局对象有以下两点不同： Vuex 的状态存储是响应式的。当 Vue 组件从 store 中读取状态的时候，若 store 中。","frontmatter":{"title":"开始","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"每一个 Vuex 应用的核心就是 store（仓库）。“store”基本上就是一个容器，它包含着你的应用中大部分的状态 (state)。Vuex 和单纯的全局对象有以下两点不同： Vuex 的状态存储是响应式的。当 Vue 组件从 store 中读取状态的时候，若 store 中。","sidebarWeight":93,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vuex/开始.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/开始.md","filePath":"posts/Vue系统教程/04-路由与状态管理/开始.md"}'),a={name:"posts/Vue系统教程/04-路由与状态管理/开始.md"};function n(u,e,i,c,p,m){return o(),s("div",null,[...e[0]||(e[0]=[r('<div><h1 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始&quot;">​</a></h1><blockquote><p>本节目标：理解“开始”的核心思路，并能把它用于实际开发或面试表达。 每一个 Vuex 应用的核心就是 store（仓库）。“store”基本上就是一个容器，它包含着你的应用中大部分的状态 (state)。Vuex 和单纯的全局对象有以下两点不同：</p></blockquote><p>Vuex 的状态存储是响应式的。当 Vue 组件从 store 中读取状态的时候，若 store 中的状态发生变化，那么相应的组件也会相应地得到高效更新。</p><p>你不能直接改变 store 中的状态。改变 store 中的状态的唯一途径就是显式地提交 (commit) mutation。这样使得我们可以方便地跟踪每一个状态的变化，从而让我们能够实现一些工具帮助我们更好地了解我们的应用。</p><p><strong>最简单的 Store</strong> 安装 Vuex 之后，让我们来创建一个 store。创建过程直截了当——仅需要提供一个初始 state 对象和一些 mutation： import { createApp } from &#39;vue&#39; import { createStore } from &#39;vuex&#39; // 创建一个新的 store 实例 const store = createStore({ state () { return { count: 0 } }, mutations: { increment (state) { state.count++ } } }) const app = createApp({ /* 根组件 */ }) // 将 store 实例作为插件安装 app.use(store)</p><p>现在，你可以通过 store.state 来获取状态对象，并通过 store.commit 方法触发状态变更： store.commit(&#39;increment&#39;) console.log(store.state.count) // -&gt; 1</p><p>在 Vue 组件中， 可以通过 this.$store 访问store实例。现在我们可以从组件的方法提交一个变更： methods: { increment() { this.$store.commit(&#39;increment&#39;) console.log(this.$store.state.count) } } 再次强调，我们通过提交 mutation 的方式，而非直接改变 store.state.count，是因为：</p><ul><li>我们想要更明确地追踪到状态的变化。这个简单的约定能够让你的意图更加明显，这样你在阅读代码的时候能更容易地解读应用内部的状态改变。</li><li>此外，这样也让我们有机会去实现一些能记录每次状态改变，保存状态快照的调试工具。有了它，我们甚至可以实现如时间穿梭般的调试体验。</li></ul><p>由于 store 中的状态是响应式的，在组件中调用 store 中的状态简单到仅需要在计算属性中返回即可。触发变化也仅仅是在组件的 methods 中提交 mutation。</p><p>接下来，我们将会更深入地探讨一些核心概念。让我们先从 State 概念开始。</p></div>',1)])])}const V=t(a,[["render",n]]);export{d as __pageData,V as default};
